import React from "react";
import { graphql } from "gatsby";
import type { HeadFC, PageProps } from "gatsby";
import { AdminLayout } from "../../../../features/admin/components/AdminLayout";
import { ItineraryDetail } from "../../../../features/admin/components/ItineraryDetail";
import SEO from "../../../../components/seo";
import data from "../../../../data/data.json";

const companyData = {
  companyName: data.name,
  address: data.address,
  city: data.city,
  province: data.province,
  country: "Canada",
  phone: data.phone,
  email: data.email,
  instagram: data.instagram,
  facebook: data.facebook,
  linkedin: "",
  postalCode: data.postalCode,
  url: data.url,
  whatsapp: "",
  menu: data.menu,
};

export default function ItineraryDetailPage({ params }: PageProps) {
  return (
    <AdminLayout title="Itinerary detail">
      <ItineraryDetail itineraryId={params["itineraryId"]} />
    </AdminLayout>
  );
}

export const Head: HeadFC = () => (
  <SEO
    data={companyData}
    title="Itinerary Detail — Jenny Adventures Admin"
    description="Admin view for itinerary details."
    pathname="/admin/itineraries"
    noindex
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
